import * as E from './engine.js?v=117';
import * as P from './pregame.js?v=102';
import * as Q from './mission.js?v=81';
import * as S from './states.js?v=109';
export const missionRules={name:'Hardlock · 信标封锁',depth:12,enemyDepth:12,exclusionZones:[]};
export function role(u){const names=Object.values(u.armyWeapons||{}).map(w=>w.en||w.name||'').join(' ');if(u.tagcom||u.baggage||u.hackingDevice==='EVO')return '后场支援';if(u.lieutenant)return '指挥支援';if(u.specialist||u.hacker||u.engineer||u.doctor||u.forwardObserver)return '任务专家';if(/Sniper|Missile|Rocket|Hyper-Rapid/i.test(names))return '远程火力';if(u.type==='TAG')return '重型突击';if(u.lieutenant)return '指挥支援';if(u.tagcom||u.baggage)return '后场支援';return '战线支援';}
export function stageUnits(s){return s.units.filter(u=>s.pregame?.stage==='deploy'&&u.team===P.deploymentTeam(s)&&u.peripheral!=='ancillary'&&!u.isDecoy&&!u.isDeployable&&(P.reserveStep(s)===s.pregame.reserves[u.team].includes(P.reserveOwner(u))));}
export function summary(u){if(u.peripheral==='ancillary')return 'Ancillary · 局中放置';if(u.offTable)return '留在桌外 · 空降入场';const b=P.deploymentBounds(u,{attemptInfiltration:!!u.infiltrationAttempt}),north=b.min===0;return `${u.infiltrationFailed?'前沿检定失败 · 己方桌边':u.impersonation?(u.infiltrationAttempt?'伪装进入敌部署区 · 须WIP':'伪装 · 敌部署区以外'):u.infiltration&&!u.infiltrationFailed?(u.infiltrationAttempt?'敌半场潜入 · 须PH−3':'潜入 · 己方半场'):u.forwardDeployment?'深入部署 +'+u.forwardDeployment+'″':'任务部署区 '+(u.deploymentDepth||12)+'″'} · Y ${b.min}–${b.max}″ · ${north?'北侧':'南侧'} · 完整底盘须在区内`;}
export function modeName(u){return u.offTable?'桌外':S.has(u,'hiddenDeployment')?'隐匿':S.has(u,'impersonation1')?'IMP-1':S.has(u,'impersonation2')?'IMP-2':S.has(u,'camouflaged')?'迷彩':S.has(u,'holomask')?'全息':'模型';}
export function positionError(s,u,p,terrain){return Q.deploymentError(u,p,s.units,terrain,s.objectives)||((s.hvts||[]).some(h=>E.edgeDistance({...u,...p},h)<=.025)?'不能部署接触 HVT':'');}
function candidates(u,terrain,{roof=false}={}){const r=E.radius(u),out=[];for(const t of terrain){if(roof){if(t.kind!=='building'||!Number.isFinite(E.terrainHeight(t)))continue;for(const x of [t.x+r+.04,t.x+t.w/2,t.x+t.w-r-.04])for(const y of [t.y+r+.04,t.y+t.h/2,t.y+t.h-r-.04])out.push({x,y,z:E.terrainHeight(t),terrainId:t.id});}else for(let q=.35;q<Math.max(t.w,t.h);q+=1.3)out.push({x:t.x-r-.01,y:t.y+Math.min(q,t.h),z:0,terrainId:t.id},{x:t.x+t.w+r+.01,y:t.y+Math.min(q,t.h),z:0,terrainId:t.id},{x:t.x+Math.min(q,t.w),y:t.y-r-.01,z:0,terrainId:t.id},{x:t.x+Math.min(q,t.w),y:t.y+t.h+r+.01,z:0,terrainId:t.id});}
 if(!roof){const b=P.deploymentBounds(u,{attemptInfiltration:!!u.infiltrationAttempt});for(let y=b.min+r+.05;y<=b.max-r;y+=1.6)for(let x=r+.05;x<=48-r;x+=1.6)out.push({x,y,z:0});}return out;}
export function recommend(s,u,terrain,{roof=false,count=3}={}){if(u.offTable||u.peripheral==='ancillary'||u.infiltrationFailed||u.infiltrationResolved||u.deploymentLocked)return [];const friendly=s.units.filter(v=>v.team===u.team&&v.id!==u.id&&!v.offTable&&!v.peripheral&&!v.isDecoy&&!v.isDeployable),index=s.units.filter(v=>v.team===u.team&&!v.peripheral&&!v.isDeployable).findIndex(v=>v.id===u.id),objectives=(s.objectives||[]).filter(o=>o.kind==='console'),lane=objectives.length?objectives[((index%objectives.length)+objectives.length)%objectives.length].x:[12,24,36][Math.max(0,index)%3],north=u.deploymentSide==='north',b=P.deploymentBounds(u,{attemptInfiltration:!!u.infiltrationAttempt}),r=role(u),reach=b.max-b.min,forward=['任务专家','重型突击','战线支援'].includes(r),desired=north?(forward?b.max-3.5:b.min+4):(forward?b.min+3.5:b.max-4);
 const valid=candidates(u,terrain,{roof}).filter(p=>!positionError(s,u,p,terrain)).map(p=>{const t=terrain.find(t=>t.id===p.terrainId),touch=t&&Math.abs(E.pointRect(p,t)-E.radius(u))<.035,back=touch&&(north?p.y<t.y:p.y>t.y+t.h),near=friendly.filter(v=>!v.deploymentPending||v.deploymentSuggested).reduce((v,n)=>Math.min(v,E.edgeDistance({...u,...p},n)),20),tag=friendly.find(v=>v.type==='TAG'&&(v.combatGroup||1)===(u.combatGroup||1)),score=(touch?30:0)+(back?10:0)-Math.abs(p.x-lane)*.7-Math.abs(p.y-desired)*1.3-Math.max(0,4-near)*12+(roof&&r==='远程火力'?10:0)-(u.tagcom&&tag?Math.abs(E.edgeDistance({...u,...p},tag)-5)*.5:0);return {...p,score,reason:(roof?'完整底盘屋顶位':touch?'贴靠 '+(t.name||'掩体'):'合法地面位')+' · '+r+' · '+(forward?'靠近控制台通路':'后场部署')};}).sort((a,b)=>b.score-a.score);
 const picks=[];for(const p of valid){if(picks.every(q=>E.dist(p,q)>3||p.z!==q.z))picks.push(p);if(picks.length===count)break;}return picks;}
export function arrange(s,terrain,units){const planned=[];const ids=new Set(units.map(u=>u.id)),base=s.units.filter(u=>!ids.has(u.id));for(const u of units){if(u.offTable||u.peripheral==='ancillary'){planned.push(u);continue;}const virtual={...s,units:[...base,...planned.map(v=>({...v,deploymentPending:false})),u]};const p=recommend(virtual,{...u,deploymentLocked:false},terrain,{count:1})[0];if(!p)throw Error((u.name||u.id)+'没有合法推荐位置');Object.assign(u,{x:p.x,y:p.y,z:p.z,wall:null,deploymentSuggested:true,deploymentReviewed:false,deploymentReason:p.reason});planned.push(u);}return planned;}
